// Background: agy writes its transcript file at
//
//	~/.gemini/antigravity-cli/brain/<conv-id>/.system_generated/logs/transcript_full.jsonl
//
// AFTER the Stop hook fires (sometimes seconds later, depending on session
// shutdown timing). Our TurnEnd event maps to Stop, so we routinely race the
// transcript write. Without PrepareTranscript, the framework's fileExists
// check fails with "transcript file not found" and our hook returns exit 1,
// terminating agy's agent turn.
//
// We briefly wait for the real transcript first. If it is still missing,
// we materialise an empty placeholder. files_touched is already captured via
// the PreToolUse hook (independent of transcript content), so condensation can
// still produce a meaningful checkpoint from an empty transcript.
func (a *AntigravityAgent) PrepareTranscript(ctx context.Context, transcriptRef string) error {
	if transcriptRef == "" {
		return nil
	}

	deadline := time.Now().Add(1 * time.Second)
	if ctxDeadline, ok := ctx.Deadline(); ok && ctxDeadline.Before(deadline) {
		deadline = ctxDeadline
	}

	for {
		info, err := os.Stat(transcriptRef)
		if err == nil {
			if info.Size() > 0 {
				return nil
			}
		} else if !os.IsNotExist(err) {
			return fmt.Errorf("antigravity: stat transcript: %w", err)
		}

		if !time.Now().Before(deadline) {
			break
		}

		wait := 50 * time.Millisecond
		if remaining := time.Until(deadline); remaining < wait {
			wait = remaining
		}
		timer := time.NewTimer(wait)
		select {
		case <-ctx.Done():
			if !timer.Stop() {
				<-timer.C
			}
			return fmt.Errorf("antigravity: context ended while waiting for transcript: %w", ctx.Err())
		case <-timer.C:
		}
	}

	if err := os.MkdirAll(filepath.Dir(transcriptRef), 0o750); err != nil {
		return fmt.Errorf("antigravity: prepare transcript dir: %w", err)
	}
	if _, err := os.Stat(transcriptRef); err == nil {
		return nil
	} else if !os.IsNotExist(err) {
		return fmt.Errorf("antigravity: stat transcript before placeholder: %w", err)
	}
	file, err := os.OpenFile(transcriptRef, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600) //nolint:gosec // path supplied by agent hook stdin
	if err != nil {
		if os.IsExist(err) {
			return nil
		}
		return fmt.Errorf("antigravity: create empty transcript placeholder: %w", err)
	}
	if err := file.Close(); err != nil {
		return fmt.Errorf("antigravity: close empty transcript placeholder: %w", err)
	}
	return nil
}

}
detectSpan.End()

// Filter and normalize all paths
_, normalizeSpan := perf.Start(ctx, "filter_and_normalize_paths")
relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
var relNewFiles, relDeletedFiles []string
if changes != nil {
	relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
	relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)

	// Merge git-status modified files as a fallback for transcript parsing.
	// Transcript parsing is the primary source for modified files, but it can miss
	// files if the agent uses an unrecognized tool or the transcript format changes.
	// Git status catches any tracked file with working-tree changes.
	relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
}

// Filter transcript-extracted files to exclude files already committed to HEAD.
// When an agent commits files mid-turn, those files are condensed by PostCommit
// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
// if it exists in HEAD with the same content as the working tree.
relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
normalizeSpan.End()

// Check if there are any changes
totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
if totalChanges == 0 {
	logging.Info(logCtx, "no files modified during session, skipping checkpoint")
	transitionSessionTurnEnd(ctx, sessionID, event)
	if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
		logging.Warn(logCtx, "failed to cleanup pre-prompt state",
			slog.String("error", cleanupErr.Error()))
	}
	return nil
}
if shouldSkipTurnEndCheckpointAfterCondensedMidTurnCommit(ag, sessionState) {
	logging.Info(logCtx, "mid-turn commit already condensed all tracked files, skipping stop checkpoint")
	transitionSessionTurnEnd(ctx, sessionID, event)
	if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
		logging.Warn(logCtx, "failed to cleanup pre-prompt state",
			slog.String("error", cleanupErr.Error()))
	}
	return nil
}

// Log file changes
logFileChanges(ctx, relModifiedFiles, relNewFiles, relDeletedFiles)

// Get git author
author, err := GetGitAuthor(ctx)
if err != nil {
	return fmt.Errorf("failed to get git author: %w", err)
}

// Get strategy and agent type
strat := GetStrategy(ctx)
agentType := ag.Type()

// Get transcript position/identifier from pre-prompt state
var transcriptIdentifierAtStart string
var transcriptLinesAtStart int
if preState != nil {
	transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
	transcriptLinesAtStart = preState.TranscriptOffset
}

// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
tokenUsage := agent.CalculateTokenUsage(ctx, ag, transcriptData, transcriptLinesAtStart, subagentsDir)

